<div id="review-loading" hidden role="status" aria-live="polite" class="fixed inset-0 z-50 bg-white/70 p-6 backdrop-blur-[1px]"><span class="sr-only">Loading reviews</span><div class="mx-auto mt-28 max-w-5xl space-y-4 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div class="h-5 w-44 animate-pulse rounded bg-slate-200"></div>@for($i=0;$i<5;$i++)<div class="h-12 animate-pulse rounded-lg bg-slate-100"></div>@endfor</div></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{
  const rows=[...document.querySelectorAll('[data-review-row]')];const rating=document.getElementById('review-rating-filter');const search=document.getElementById('review-search');const empty=document.getElementById('review-filter-empty');const count=document.getElementById('review-count');
  const apply=()=>{let shown=0;const q=(search?.value||'').toLowerCase().trim();rows.forEach(row=>{const matches=(!rating?.value||row.dataset.rating===rating.value)&&(!q||(row.dataset.search||'').includes(q));row.hidden=!matches;if(matches)shown++});if(empty)empty.hidden=shown!==0;if(count)count.textContent=`Showing ${shown} of ${rows.length} reviews on this page`;};rating?.addEventListener('change',apply);search?.addEventListener('input',apply);apply();
  const loading=document.getElementById('review-loading');document.getElementById('review-filters')?.addEventListener('submit',()=>{if(loading)loading.hidden=false});document.querySelectorAll('nav[aria-label="Review pages"] a').forEach(link=>link.addEventListener('click',()=>{if(link.getAttribute('aria-disabled')!=='true'&&loading)loading.hidden=false}));
  const dialog=document.getElementById('review-moderation-dialog');let selectedForm=null;document.querySelectorAll('[data-review-moderation-form]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();selectedForm=form;const status=form.dataset.status;document.getElementById('review-dialog-title').textContent=status==='approved'?'Approve this review?':status==='hidden'?'Hide this review?':'Reject this review?';document.getElementById('review-dialog-copy').textContent=`Confirm ${status} for “${form.dataset.reviewTitle}”. This will update the moderation status in ReviewService. The service does not store a moderation reason or operator identity.`;document.getElementById('review-dialog-confirm').textContent=status==='approved'?'Approve review':status==='hidden'?'Hide review':'Reject review';dialog.showModal()}));document.getElementById('review-dialog-cancel')?.addEventListener('click',()=>dialog.close());document.getElementById('review-dialog-confirm')?.addEventListener('click',()=>{if(selectedForm){const button=selectedForm.querySelector('button[type="submit"]');if(button){button.disabled=true;button.textContent='Saving…'}selectedForm.submit()}});dialog?.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
});
</script>
</body></html>
